SET NAMES utf8mb4;
UPDATE sys_user SET real_name=CONVERT(UNHEX('E99988E699A8') USING utf8mb4) WHERE username LIKE 'DEMO_U_%' AND MOD(CAST(SUBSTRING_INDEX(username, '_', -1) AS UNSIGNED), 10)=0;
