UPDATE sys_user u JOIN area a ON a.id=u.area_id SET u.address=CONCAT(CONVERT(UNHEX('E7A4BAE88C83E58CBA41') USING utf8mb4), SUBSTRING_INDEX(u.username, '_', -1), CONVERT(UNHEX('E58FB7E6A5BC') USING utf8mb4)) WHERE a.area_code='A001' AND u.username LIKE 'DEMO_U_%';
UPDATE water_meter m JOIN area a ON a.id=m.area_id SET m.install_address=CONCAT(CONVERT(UNHEX('E7A4BAE88C83E58CBA41') USING utf8mb4), ' ', m.meter_no) WHERE a.area_code='A001' AND m.remark='DEMO_SHOW';
